// UI.keys — central keyboard shortcut registry. Combos like "mod+k", "shift+/", "escape".

const bindings = new Map(); // id -> { combo, handler, description }
let installed = false;
const isMac = () => /Mac|iPhone|iPad/.test(navigator.platform || navigator.userAgent);

function parse(combo) {
  const parts = combo.toLowerCase().split("+").map(s => s.trim());
  const key = parts.pop();
  return { key, mod: parts.includes("mod"), ctrl: parts.includes("ctrl"), alt: parts.includes("alt"), shift: parts.includes("shift"), meta: parts.includes("meta") };
}

function matches(spec, e) {
  const mod = isMac() ? e.metaKey : e.ctrlKey;
  return (
    e.key.toLowerCase() === spec.key &&
    (spec.mod ? mod : isMac() ? e.metaKey === spec.meta : e.ctrlKey === (spec.ctrl || false) && e.metaKey === spec.meta) &&
    e.altKey === spec.alt &&
    (e.shiftKey === spec.shift || spec.key.length > 1 || /[^a-z0-9]/.test(spec.key))
  );
}

function install() {
  if (installed) return;
  installed = true;
  document.addEventListener("keydown", e => {
    const t = e.target;
    const typing = t instanceof HTMLElement && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName));
    for (const b of bindings.values()) {
      if (typing && !b.allowInInput && !(b.spec.mod || b.spec.ctrl || b.spec.alt || b.spec.meta)) continue;
      if (matches(b.spec, e)) {
        e.preventDefault();
        b.handler(e);
        return;
      }
    }
  });
}

export const keys = {
  /** Register a shortcut. Returns an unregister function. */
  register(id, combo, handler, options = {}) {
    install();
    if (__DEV__ && bindings.has(id)) console.warn(`[UI-W010] key binding "${id}" replaced`);
    bindings.set(id, { combo, spec: parse(combo), handler, description: options.description ?? "", allowInInput: !!options.allowInInput });
    return () => bindings.delete(id);
  },
  unregister(id) { bindings.delete(id); },
  list() { return [...bindings].map(([id, b]) => ({ id, combo: b.combo, description: b.description })); },
  /** Platform-sensitive display parts, e.g. "mod+k" -> ["⌘","K"] or ["Ctrl","K"]. */
  format(combo) {
    const mac = isMac();
    return combo.split("+").map(p => {
      const k = p.trim().toLowerCase();
      if (k === "mod") return mac ? "⌘" : "Ctrl";
      if (k === "ctrl") return mac ? "⌃" : "Ctrl";
      if (k === "alt") return mac ? "⌥" : "Alt";
      if (k === "shift") return mac ? "⇧" : "Shift";
      if (k === "meta") return mac ? "⌘" : "Win";
      if (k === "escape") return "Esc";
      return k.length === 1 ? k.toUpperCase() : k[0].toUpperCase() + k.slice(1);
    });
  }
};
