// UI.i18n — message catalogue with English defaults. Components call UI.i18n.t("key").

const defaults = {
  "select.empty": "No options found",
  "select.placeholder": "Select…",
  "modal.close": "Close",
  "modal.ok": "OK",
  "modal.cancel": "Cancel",
  "toast.dismiss": "Dismiss",
  "input.showPassword": "Show password",
  "input.hidePassword": "Hide password",
  "pagination.previous": "Previous page",
  "pagination.next": "Next page"
};

let messages = { ...defaults };

export const i18n = {
  t(key, vars = {}) {
    const s = messages[key] ?? key;
    return s.replace(/\{(\w+)\}/g, (_, k) => (k in vars ? String(vars[k]) : `{${k}}`));
  },
  set(catalogue) { messages = { ...messages, ...catalogue }; },
  reset() { messages = { ...defaults }; },
  keys() { return Object.keys(defaults); }
};
