// Factory for tier-A presentational components: the host element gets BEM classes, children stay untouched.
import { UIElement } from "../base/UIElement.js";

/**
 * @param {object} spec
 * @param {string} spec.tag          custom element tag
 * @param {string} spec.cls          base class
 * @param {object} [spec.props]      props schema
 * @param {object} [spec.modifiers]  prop -> pattern ("ui-x--{}" or "ui-x--flag")
 * @param {object} spec.docs         static docs (kept only when __DOCS__)
 */
export function hostComponent({ tag, cls, props = {}, modifiers = {}, docs }) {
  const Class = class extends UIElement {
    static tag = tag;
    static props = props;
    static host = { class: cls, modifiers };
    static docs = __DOCS__ ? docs : null;
  };
  Object.defineProperty(Class, "name", { value: "UI" + tag.slice(3).replace(/(^|-)(\w)/g, (_, __, c) => c.toUpperCase()) });
  return Class;
}

export const str = (attribute, def = "") => ({ type: "string", attribute, default: def });
export const bool = attribute => ({ type: "boolean", attribute, default: false });
export const num = (attribute, def = null) => ({ type: "number", attribute, default: def });
