// UI.commands — command registry used by <ui-command-palette>.
import { keys } from "./keys.js";

const registry = new Map();

export const commands = {
  register(cmd) {
    if (!cmd?.id || typeof cmd.run !== "function") throw new Error("UI.commands.register: { id, label, run } required");
    if (__DEV__ && registry.has(cmd.id)) console.warn(`[UI-W011] duplicate command id "${cmd.id}"`);
    registry.set(cmd.id, cmd);
    const off = cmd.shortcut ? keys.register(`cmd:${cmd.id}`, cmd.shortcut, () => cmd.run(), { description: cmd.label }) : null;
    return () => { registry.delete(cmd.id); off?.(); };
  },
  list() { return [...registry.values()]; },
  run(id) { return registry.get(id)?.run(); }
};
