// Template directives. Plain marker objects interpreted by render().

export const nothing = Symbol("ui:nothing");

/** Insert a trusted HTML string. The only sanctioned innerHTML sink besides the template parser. */
export function unsafeHTML(value) {
  return { __ui: "unsafe", value };
}

/** Keyed list. `keyFn(item)` -> key, `itemFn(item, key, index)` -> TemplateResult. */
export function repeat(items, keyFn, itemFn) {
  return { __ui: "repeat", items, keyFn, itemFn };
}

/** Build a class string from strings / objects / falsy values. */
export function classes(...args) {
  const out = [];
  for (const a of args) {
    if (!a) continue;
    if (typeof a === "string") out.push(a);
    else if (typeof a === "object") for (const [k, v] of Object.entries(a)) if (v) out.push(k);
  }
  return out.join(" ");
}

/** Callback receiving the element the directive is bound to (use as `ref=${ref(fn)}`). */
export function ref(callback) {
  return { __ui: "ref", callback };
}
