import { UIElement } from "../../base/UIElement.js";
import { hostComponent, bool } from "../host-component.js";

const part = (tag, cls, summary) =>
  hostComponent({ tag, cls, docs: { summary, category: "Shell", slots: { "": "Content." }, examples: [`<${tag}>Content</${tag}>`, `<${tag}><strong>Rich</strong></${tag}>`] } });

export const UITopbar = part("ui-topbar", "ui-topbar", "Application top bar.");
export const UISidebar = part("ui-sidebar", "ui-sidebar", "Application sidebar.");
export const UISidebarHeader = part("ui-sidebar-header", "ui-sidebar__header", "Sidebar header.");
export const UISidebarBody = part("ui-sidebar-body", "ui-sidebar__body", "Sidebar body.");
export const UISidebarFooter = part("ui-sidebar-footer", "ui-sidebar__footer", "Sidebar footer.");
export const UINav = part("ui-nav", "ui-nav", "Navigation list.");
export const UINavSection = part("ui-nav-section", "ui-nav__section", "Navigation section.");

/** Application shell. Direct children are grid items — no wrappers are added. */
export class UIShell extends UIElement {
  static tag = "ui-shell";
  static props = {
    collapsed: bool("collapsed"),
    sidebarOpen: bool("sidebar-open"),
    persist: bool("persist")
  };
  static host = { class: "ui-shell", modifiers: { collapsed: "ui-shell--collapsed" } };
  static docs = __DOCS__
    ? {
        summary: "Application shell with collapsible sidebar and top bar.",
        category: "Shell",
        props: { collapsed: "Collapse the sidebar.", sidebarOpen: "Mobile sidebar open state.", persist: "Remember the collapsed state in localStorage." },
        events: { "ui-shell-change": "Collapsed or sidebar state changed." },
        methods: { toggle: "Toggle collapsed state.", openSidebar: "Open the mobile sidebar.", closeSidebar: "Close the mobile sidebar." },
        slots: { "": "ui-topbar, ui-sidebar and page content." },
        examples: ["<ui-shell><ui-topbar>App</ui-topbar><ui-sidebar>Menu</ui-sidebar><main>Content</main></ui-shell>", "<ui-shell collapsed><ui-sidebar>Menu</ui-sidebar><main>Content</main></ui-shell>"]
      }
    : null;

  init() {
    if (this.persist) {
      try { this.collapsed = localStorage.getItem("ui-shell-collapsed") === "true"; } catch { /* ignore */ }
    }
    this.on("keydown", e => { if (e.key === "Escape" && this.sidebarOpen) this.closeSidebar(); });
    this.addEventListener("command", e => {
      if (e.command === "--ui-toggle") { e.preventDefault(); this.toggle(); }
    });
  }

  propsChanged(name, old, next) {
    super.propsChanged(name, old, next);
    if (!this.__connected) return;
    this.toggleAttribute("data-sidebar-open", this.sidebarOpen);
    if (this.persist && name === "collapsed") {
      try { localStorage.setItem("ui-shell-collapsed", String(this.collapsed)); } catch { /* ignore */ }
    }
    if (name === "collapsed" || name === "sidebarOpen") this.emit("ui-shell-change", { collapsed: this.collapsed, sidebarOpen: this.sidebarOpen });
  }

  toggle() { this.collapsed = !this.collapsed; }
  openSidebar() { this.sidebarOpen = true; }
  closeSidebar() { this.sidebarOpen = false; }
}

/** Navigation item rendering its own anchor. */
export class UINavItem extends UIElement {
  static tag = "ui-nav-item";
  static props = {
    href: { type: "string", attribute: "href", default: "" },
    icon: { type: "string", attribute: "icon", default: "" },
    match: { type: "string", attribute: "match", default: "" }
  };
  static docs = __DOCS__
    ? {
        summary: "Navigation item with icon and label.",
        category: "Shell",
        props: { href: "Link target.", icon: "Font Awesome icon name.", match: "exact or prefix: derive active state from location." },
        slots: { "": "Label text." },
        examples: ['<ui-nav><ui-nav-item href="/" icon="house">Home</ui-nav-item></ui-nav>', '<ui-nav><ui-nav-item href="/docs" match="prefix">Docs</ui-nav-item></ui-nav>']
      }
    : null;

  template() {
    const a = document.createElement("a");
    a.className = "ui-nav__item";
    a.href = this.href || "#";
    if (this.icon) {
      const i = document.createElement("i");
      i.className = `ui-nav__icon fa-solid fa-${this.icon}`;
      i.setAttribute("aria-hidden", "true");
      a.append(i);
    }
    const label = document.createElement("span");
    label.className = "ui-nav__label";
    label.append(...this.slotted.map(n => n.cloneNode(true)));
    a.append(label);
    const path = location.pathname;
    const active = this.match === "exact" ? path === a.pathname : this.match === "prefix" ? path.startsWith(a.pathname) : false;
    if (active) { a.setAttribute("aria-current", "page"); a.classList.add("ui-nav__item--active"); }
    return a;
  }
}

export class UINavbarLink extends UIElement {
  static tag = "ui-navbar-link";
  static host = { class: "ui-navbar-link" };
  static props = { href: { type: "string", attribute: "href", default: "" }, icon: { type: "string", attribute: "data-icon", default: "" } };
  static docs = __DOCS__
    ? { summary: "Top bar link with optional icon.", category: "Shell", props: { href: "Link target.", icon: "Font Awesome icon name." }, slots: { "": "Label." }, examples: ['<ui-navbar-link href="/">Home</ui-navbar-link>', '<ui-navbar-link href="/x" icon="gear">Settings</ui-navbar-link>'] }
    : null;
}
